from scipy.optimize import minimize
import numpy as np

def f(t):
    # f(t) = (2t+1)^3 / (3t)
    if t <= 0:
        return float('inf')
    return (2*t + 1)**3 / (3*t)

# We expect the minimum around t = 1/4 = 0.25
t_initial_guess = 0.25

# Find the minimum using optimization
res = minimize(f, x0=t_initial_guess, method='Nelder-Mead')

print(f"Minimum value found: {res.fun}")
print(f"At t={res.x[0]}")
